549	    /**
550	     * The fixed public holidays the business-day roll skips. A date landing on any of these is
551	     * advanced, along with weekends, until it reaches the next non-holiday business day.
552	     */
553	    private static final java.util.Set<LocalDate> PUBLIC_HOLIDAYS = java.util.Set.of(
554	        LocalDate.parse("2026-01-01"), LocalDate.parse("2026-01-26"),
555	        LocalDate.parse("2026-04-25"), LocalDate.parse("2026-12-25"),
556	        LocalDate.parse("2026-12-28"));
557	
558	    /**
559	     * Rolls a date forward to the next business day: a Saturday, Sunday or listed public holiday is
560	     * advanced one day at a time until it reaches a weekday that is not a public holiday, while a
561	     * date already on such a business day is returned unchanged.
562	     *
563	     * @param date the date to adjust
564	     * @return the same date when it is a non-holiday weekday, otherwise the next such business day
565	     */
566	    private LocalDate toBusinessDay(LocalDate date) {
567	        while (date.getDayOfWeek() == java.time.DayOfWeek.SATURDAY
568	                || date.getDayOfWeek() == java.time.DayOfWeek.SUNDAY
569	                || PUBLIC_HOLIDAYS.contains(date)) {
570	            date = date.plusDays(1);
571	        }
572	        return date;
573	    }
