899	    /**
900	     * Pattern for a syntactically valid email address: a non-empty local part, an {@code @},
901	     * and a domain containing at least one dot, none of the parts holding whitespace or a
902	     * second {@code @}.
903	     */
904	    private static final java.util.regex.Pattern EMAIL_PATTERN =
905	        java.util.regex.Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
906	
907	    /**
908	     * Disposable email domains an owner may not register with. An email whose domain (compared
909	     * case-insensitively) is one of these is rejected, since it identifies a throwaway mailbox.
910	     */
911	    private static final java.util.Set<String> DISPOSABLE_EMAIL_DOMAINS =
912	        java.util.Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
913	
914	    /**
915	     * Normalizes an optional owner email. An email is optional, so a {@code null} value is
916	     * accepted and returned unchanged. When present it must be a syntactically valid address
917	     * whose domain is not on the disposable-domain blocklist (see
918	     * {@link #DISPOSABLE_EMAIL_DOMAINS}); the value is stored and returned lower-cased. When
919	     * present but syntactically invalid or on a disposable domain an
920	     * {@link InvalidFieldsException} is thrown, which the exception advice renders as a 400
921	     * response naming the {@code email} field.
922	     *
923	     * @param email the submitted email value, or {@code null} when omitted
924	     * @return the lower-cased email, or {@code null} when none was supplied
925	     */
926	    private String normalizeEmail(String email) {
927	        if (email == null) {
928	            return null;
929	        }
930	        String trimmed = email.trim();
931	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
932	            throw new InvalidFieldsException(List.of("email"));
933	        }
934	        String domain = trimmed.substring(trimmed.lastIndexOf('@') + 1).toLowerCase(java.util.Locale.ROOT);
935	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
936	            throw new InvalidFieldsException(List.of("email"));
937	        }
938	        return canonicalEmail(trimmed);
939	    }
