941	    /**
942	     * Reduces an email to the canonical form used both to store it and to compare it against
943	     * other owners' emails: surrounding whitespace is trimmed and the value is lower-cased. A
944	     * {@code null} email (none was supplied) canonicalizes to {@code null}. Unlike
945	     * {@link #normalizeEmail(String)} no validation is performed, so this can be applied to a
946	     * value read back off an existing owner without risk of rejecting it. This is the single
947	     * definition of email identity: two emails denote the same address exactly when they
948	     * canonicalize to the same value, so an email stored via {@link #normalizeEmail(String)} and
949	     * an email already on an existing owner can be compared for equality after both pass through
950	     * here. For example {@code "  Jane@Example.COM "} canonicalizes to {@code "jane@example.com"}.
951	     *
952	     * @param email the email to canonicalize, or {@code null} when none was supplied
953	     * @return the trimmed, lower-cased email, or {@code null} when {@code email} is {@code null}
954	     */
955	    private String canonicalEmail(String email) {
956	        if (email == null) {
957	            return null;
958	        }
959	        return email.trim().toLowerCase(java.util.Locale.ROOT);
960	    }
