962	    /**
963	     * Validates an optional owner postcode. A postcode is optional, so a {@code null} value is
964	     * accepted and left unchanged. When present it must be exactly 4 digits, and when the owner's
965	     * city has a known region (see {@link Owner#regionForCity(String)}) the postcode must fall
966	     * within that region's inclusive range ({@code NSW 2000-2099}, {@code VIC 3000-3099},
967	     * {@code QLD 4000-4099}, see {@link Owner#postcodeRangeForRegion(String)}). A city with no known
968	     * region admits any 4-digit postcode. When present but malformed or out of range for the city's
969	     * region an {@link InvalidFieldsException} is thrown, which the exception advice renders as a
970	     * 400 response naming the {@code postcode} field.
971	     *
972	     * @param postcode the submitted postcode, or {@code null} when omitted
973	     * @param city the owner's city, used to resolve the region whose range the postcode must satisfy
974	     */
975	    private void validatePostcode(String postcode, String city) {
976	        if (postcode == null) {
977	            return;
978	        }
979	        if (!postcode.matches("^[0-9]{4}$")) {
980	            throw new InvalidFieldsException(List.of("postcode"));
981	        }
982	        int[] range = Owner.postcodeRangeForRegion(Owner.regionForCity(city));
983	        if (range != null) {
984	            int value = Integer.parseInt(postcode);
985	            if (value < range[0] || value > range[1]) {
986	                throw new InvalidFieldsException(List.of("postcode"));
987	            }
988	        }
989	    }
