991	    /**
992	     * Rejects a new owner that is an exact identity duplicate of an existing owner. An owner's
993	     * identity is its single derived identity key (see
994	     * {@link Owner#identityKey(String, String, String)}) — the SHA-256 hex digest over its
995	     * normalized {@code telephone}, canonical {@code email} and the Soundex code of its
996	     * {@code lastName} — so a new owner is a hard duplicate only when some existing, non-deleted
997	     * owner carries the same identity key. The email-domain blocklist has already been applied when
998	     * the email was normalized ahead of this check, so a disposable-domain email is rejected before
999	     * duplicate detection runs. Two owners that merely belong to the same household (the same last
1000	     * name and postcode) but carry different telephones now have distinct identity keys and are not
1001	     * rejected here; such a near-match is instead recorded as a soft {@code possibleDuplicate} (see
1002	     * {@link #applyPossibleDuplicate(Owner, OwnerFieldsDto)}). When an existing owner shares the new
1003	     * owner's identity key a {@link DuplicateIdentityException} is thrown, which the exception advice
1004	     * renders as a 409 Conflict response. Setting {@code sharesHousehold} declares the owner a
1005	     * deliberate household member and bypasses this block.
1006	     *
1007	     * @param ownerFieldsDto the submitted owner fields, already normalized in place
1008	     */
1009	    private void rejectDuplicateIdentity(OwnerFieldsDto ownerFieldsDto) {
1010	        if (sharesHousehold(ownerFieldsDto)) {
1011	            return;
1012	        }
1013	        String identityKey = Owner.identityKey(ownerFieldsDto.getTelephone(),
1014	            ownerFieldsDto.getEmail(), ownerFieldsDto.getLastName());
1015	        boolean taken = this.clinicService.findAllOwners().stream()
1016	            .filter(existing -> !Owner.isDeleted(existing.getDeleted()))
1017	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
1018	        if (taken) {
1019	            throw new DuplicateIdentityException(identityKey);
1020	        }
1021	    }
1022	
1023	    /**
1024	     * Assigns the deterministic shared {@code householdId} to a newly created owner. The identifier
1025	     * is derived from the owner's household identity — its {@code lastName} and {@code postcode} (see
1026	     * {@link #householdIdFor(String, String)}) — so every owner sharing a last name and postcode
1027	     * resolves to the same stable value automatically, without any explicit linking. An owner without
1028	     * a postcode belongs to no shared household and is left without a household identifier.
1029	     *
1030	     * @param owner the newly created owner, mutated in place with its household identifier
1031	     */
1032	    private void assignHousehold(Owner owner) {
1033	        owner.setHouseholdId(householdIdFor(owner.getLastName(), owner.getPostcode()));
1034	    }
1035	
1036	    /**
1037	     * Reports whether a submitted owner opted into sharing a household, i.e. whether its request
1038	     * carried {@code sharesHousehold} set to {@code true}. A {@code null} or {@code false} flag is
1039	     * not opting in. This is the single reading of the {@code sharesHousehold} intent, shared by
1040	     * every rule that treats a declared household member differently from an independent owner.
1041	     *
1042	     * @param ownerFieldsDto the submitted owner fields carrying the {@code sharesHousehold} flag
1043	     * @return {@code true} when the request opted into sharing a household
1044	     */
1045	    private boolean sharesHousehold(OwnerFieldsDto ownerFieldsDto) {
1046	        return Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
1047	    }
1048	
1049	    /**
1050	     * Derives the stable {@code householdId} shared by every owner in the household identified by
1051	     * the given {@code lastName} and {@code postcode}. The household is keyed on {@code (lastName,
1052	     * postcode)}: the normalized last name and the postcode are hashed with SHA-256 and the leading
1053	     * 12 hex characters of the digest form the identifier, so any two owners sharing a last name and
1054	     * postcode — regardless of creation order or address — resolve to the same identifier
1055	     * automatically. An owner without a postcode belongs to no shared household, so {@code null} is
1056	     * returned.
1057	     *
1058	     * @param lastName the household's last name
1059	     * @param postcode the household's postcode, or {@code null} when the owner has none
1060	     * @return the deterministic household identifier, or {@code null} when {@code postcode} is {@code null}
1061	     */
1062	    private String householdIdFor(String lastName, String postcode) {
1063	        if (postcode == null) {
1064	            return null;
1065	        }
1066	        return shaHex(householdKey(lastName, postcode), 12);
1067	    }
1068	
1069	    /**
1070	     * Builds the canonical household key that identifies the household a {@code lastName} and
1071	     * {@code postcode} belong to: the normalized last name (case-insensitive, with collapsed
1072	     * whitespace) joined to the postcode by {@code '|'}. This is the single definition of which
1073	     * owner fields make up a household and how they are normalized;
1074	     * {@link #householdIdFor(String, String)} hashes this key into the stored identifier, so any two
1075	     * owners in the same household resolve to the same key and therefore the same identifier.
1076	     *
1077	     * @param lastName the household's last name
1078	     * @param postcode the household's postcode
1079	     * @return the normalized household key
1080	     */
1081	    private String householdKey(String lastName, String postcode) {
1082	        return collapseWhitespace(lastName).toLowerCase(java.util.Locale.ROOT) + "|" + postcode;
1083	    }
1084	
1085	    /**
1086	     * Returns the leading {@code hexChars} upper-case hex characters of the SHA-256 digest of a
1087	     * string, the form used by the derived owner codes (for example the customer code and household
1088	     * identifier). Delegates to {@link Owner#shaHexPrefix(String, int)}, the single definition of the
1089	     * truncated upper-case hex derivation, so {@code hexChars} characters cover the leading
1090	     * {@code ceil(hexChars / 2)} bytes of the digest.
1091	     *
1092	     * @param input the string to hash
1093	     * @param hexChars the number of leading upper-case hex characters to return
1094	     * @return the first {@code hexChars} upper-case hex characters of the SHA-256 digest
1095	     */
1096	    private String shaHex(String input, int hexChars) {
1097	        return Owner.shaHexPrefix(input, hexChars);
1098	    }
1099	
1100	    /**
1101	     * Returns the owners that belong to the household identified by the given {@code householdId},
1102	     * i.e. every owner carrying that exact identifier. Soft-deleted owners are included, so a caller
1103	     * that must ignore deleted owners (as {@link #rejectDuplicateIdentity(OwnerFieldsDto)} does)
1104	     * filters them out itself. The owners are taken from the current set, so after a create the
1105	     * result includes the newly persisted owner. An owner without a household (a {@code null}
1106	     * identifier) belongs to no shared household, so an empty list is returned. This is the single
1107	     * definition of a household's members, shared by every rule that reasons about the owners
1108	     * sharing a household (the household-duplicate block and the household member count).
1109	     *
1110	     * @param householdId the shared household identifier, or {@code null} when the owner shares no household
1111	     * @return the owners in the household, or an empty list when {@code householdId} is {@code null}
1112	     */
1113	    private List<Owner> householdMembers(String householdId) {
1114	        if (householdId == null) {
1115	            return List.of();
1116	        }
1117	        return this.clinicService.findAllOwners().stream()
1118	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
1119	            .collect(Collectors.toList());
1120	    }
1121	
1122	    /**
1123	     * Counts the owners that belong to the household identified by the given {@code householdId} (see
1124	     * {@link #householdMembers(String)}), i.e. every owner carrying that exact identifier. The count
1125	     * is taken against the current set of owners, so after a create it reflects the household's size
1126	     * including the newly persisted owner. An owner without a household (a {@code null} identifier)
1127	     * belongs to no shared household and yields {@code 0}.
1128	     *
1129	     * @param householdId the shared household identifier, or {@code null} when the owner shares no household
1130	     * @return the number of owners in the household, or {@code 0} when {@code householdId} is {@code null}
1131	     */
1132	    private int countHouseholdMembers(String householdId) {
1133	        return householdMembers(householdId).size();
1134	    }
1135	
1136	    /**
1137	     * Stamps an owner with its household member count, the number of owners sharing its household
1138	     * (see {@link #countHouseholdMembers(String)}), so every value the owner derives from its
1139	     * household size (its membership factor and level) reads a populated count rather than the
1140	     * unstamped default. This is the single definition of hydrating an owner with its household
1141	     * member count, shared by the create and read paths that render an owner's derived values.
1142	     *
1143	     * @param owner the owner to stamp, mutated in place with its household member count
1144	     */
1145	    private void applyHouseholdMemberCount(Owner owner) {
1146	        owner.setHouseholdMemberCount(countHouseholdMembers(owner.getHouseholdId()));
1147	    }
1148	
1149	    /**
1150	     * Resolves the household level ceiling a newly created owner is subject to: one above the
1151	     * current maximum {@code membershipLevel} among the existing, non-deleted owners already
1152	     * sharing its household (see {@link #householdMembers(String)}). Each existing member is
1153	     * stamped with its household member count first so its {@link Owner#getMembershipLevel()}
1154	     * reads a populated count, mirroring how the create and read paths render a member's derived
1155	     * level. The ceiling is taken before the new owner is persisted, so it reflects only the
1156	     * members already in the household. When the owner joins an empty household — no household
1157	     * identifier, or no existing member — no ceiling applies and {@code null} is returned, letting
1158	     * the owner earn its uncapped level (see {@link Owner#cappedMembershipLevel(int, Integer)}).
1159	     *
1160	     * @param householdId the shared household identifier of the owner being created, or {@code null}
1161	     * @return one above the household's current maximum membership level, or {@code null} when no ceiling applies
1162	     */
1163	    private Integer householdMembershipLevelCap(String householdId) {
1164	        java.util.OptionalInt max = householdMembers(householdId).stream()
1165	            .filter(existing -> !Owner.isDeleted(existing.getDeleted()))
1166	            .peek(this::applyHouseholdMemberCount)
1167	            .mapToInt(Owner::getMembershipLevel)
1168	            .max();
1169	        return max.isPresent() ? max.getAsInt() + 1 : null;
1170	    }
1171	
1172	    /**
1173	     * Collapses a field for household comparison: leading and trailing whitespace is trimmed and
1174	     * every internal run of whitespace is reduced to a single space. A {@code null} value collapses
1175	     * to the empty string. Case is left untouched so callers can compare case-insensitively.
1176	     *
1177	     * @param value the value to collapse, or {@code null}
1178	     * @return the whitespace-collapsed value, never {@code null}
1179	     */
1180	    private String collapseWhitespace(String value) {
1181	        if (value == null) {
1182	            return "";
1183	        }
1184	        return value.trim().replaceAll("\\s+", " ");
1185	    }
1186	
1187	    /**
1188	     * Common street-type abbreviations expanded during address normalization, keyed by their
1189	     * upper-cased token.
1190	     */
1191	    private static final java.util.Map<String, String> ADDRESS_ABBREVIATIONS =
1192	        java.util.Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
1193	
1194	    /**
1195	     * Normalizes a submitted address into the canonical form stored and returned for an owner:
1196	     * leading and trailing whitespace is trimmed, every internal run of whitespace is collapsed to
1197	     * a single space, the value is upper-cased, and common street-type abbreviations are expanded
1198	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} value
1199	     * normalizes to the empty string, and an address that holds only whitespace normalizes to the
1200	     * empty string so the required-field check rejects it. For example {@code "  12  main  st "}
1201	     * becomes {@code "12 MAIN STREET"}. This is the single definition of address normalization used
1202	     * everywhere an address is stored or compared.
1203	     *
1204	     * @param address the submitted address value, or {@code null}
1205	     * @return the normalized address, never {@code null}
1206	     */
1207	    private String normalizeAddress(String address) {
1208	        if (address == null) {
1209	            return "";
1210	        }
1211	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(java.util.Locale.ROOT);
1212	        if (collapsed.isEmpty()) {
1213	            return "";
1214	        }
1215	        String[] tokens = collapsed.split(" ");
1216	        StringBuilder sb = new StringBuilder(collapsed.length());
1217	        for (int i = 0; i < tokens.length; i++) {
1218	            if (i > 0) {
1219	                sb.append(' ');
1220	            }
1221	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
1222	        }
1223	        return sb.toString();
1224	    }
1225	}
